INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('d84c29ca-1ed2-5aa2-b86c-f1408d07b213','a0000000-0000-4000-8000-0000000000a2','Блок 1. The Indefinite Article (a/an)',1,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f5b90e17-57d7-5cf2-b4fb-93cf435c8b03','d84c29ca-1ed2-5aa2-b86c-f1408d07b213','The Indefinite Article (a/an)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'a' before words beginning with a consonant sound (a horse, a guitar) and 'an' before words beginning with a vowel sound (an owl, an egg)."}, {"type": "rule", "text": "We use a/an only with singular countable nouns. We do not use a/an with plural or uncountable nouns."}, {"type": "text", "text": "Careful: it is the sound that matters, not the letter. an hour (silent h), a university (/juː/ sound)."}, {"type": "examples", "items": ["a shark", "an elephant", "a watermelon", "an owl", "a suitcase", "an egg"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d0646692-1a2c-5485-8c6b-90e18e1cb54b','f5b90e17-57d7-5cf2-b4fb-93cf435c8b03',0,'SORT_COLUMNS','Распредели слова по колонкам ''a'' и ''an''.',$j${"columns": [{"id": "c1", "label": "a"}, {"id": "c2", "label": "an"}], "items": [{"id": "i1", "label": "blackboard"}, {"id": "i2", "label": "accordion"}, {"id": "i3", "label": "owl"}, {"id": "i4", "label": "horse"}, {"id": "i5", "label": "egg"}, {"id": "i6", "label": "guitar"}, {"id": "i7", "label": "elephant"}, {"id": "i8", "label": "tiger"}, {"id": "i9", "label": "watermelon"}, {"id": "i10", "label": "suitcase"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d0646692-1a2c-5485-8c6b-90e18e1cb54b',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c2", "i4": "c1", "i5": "c2", "i6": "c1", "i7": "c2", "i8": "c1", "i9": "c1", "i10": "c1"}}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('282135bb-5c0a-5553-abe2-e9ae67110c89','f5b90e17-57d7-5cf2-b4fb-93cf435c8b03',1,'FILL_BLANK','Впиши артикль ''a'' или ''an''.',$j${"items": [{"before": "", "after": "orange"}, {"before": "", "after": "dog"}, {"before": "", "after": "umbrella"}, {"before": "", "after": "hour"}, {"before": "", "after": "university"}, {"before": "", "after": "island"}]}$j$::jsonb,10);
