INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('490b89c0-277a-550e-b687-daed35dc7a1f','a0000000-0000-4000-8000-0000000000a2','Блок 2. The Definite Article (the)',2,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('1212db50-551f-5872-86af-6e985bc55a9d','490b89c0-277a-550e-b687-daed35dc7a1f','The Definite Article (the)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'the' before things that are unique or already mentioned, and before the names of rivers, seas, oceans, mountain ranges, deserts and famous monuments/buildings."}, {"type": "rule", "text": "We do NOT use 'the' before the names of single mountains, single lakes, most countries, cities and streets."}, {"type": "examples", "items": ["the Eiffel Tower", "the Sydney Opera House", "Mount Everest", "Lake Geneva", "the Nile", "the Alps"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e7175fa4-1a25-590e-a5c2-c6e62b8045fe','1212db50-551f-5872-86af-6e985bc55a9d',0,'CHOOSE','Выбери ''the'' или ''-'' (без артикля).',$j${"items": [{"before": "", "after": "Eiffel Tower is in Paris.", "options": [{"id": "o1", "label": "The"}, {"id": "o2", "label": "-"}]}, {"before": "", "after": "Mount Everest is very high.", "options": [{"id": "o1", "label": "The"}, {"id": "o2", "label": "-"}]}, {"before": "We visited", "after": "Sydney Opera House.", "options": [{"id": "o1", "label": "the"}, {"id": "o2", "label": "-"}]}, {"before": "They sailed on", "after": "Lake Geneva.", "options": [{"id": "o1", "label": "the"}, {"id": "o2", "label": "-"}]}, {"before": "", "after": "Nile is a very long river.", "options": [{"id": "o1", "label": "The"}, {"id": "o2", "label": "-"}]}, {"before": "She climbed", "after": "Alps last summer.", "options": [{"id": "o1", "label": "the"}, {"id": "o2", "label": "-"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e7175fa4-1a25-590e-a5c2-c6e62b8045fe',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
