INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('34a3467c-4546-5ec9-8e65-c83c9bba5c2d','a0000000-0000-4000-8000-0000000000a2','Блок 3. Plurals',3,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e4a8fe05-9a1c-5cff-abf7-4fef0795c027','34a3467c-4546-5ec9-8e65-c83c9bba5c2d','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns form the plural by adding -s (book → books, key → keys)."}, {"type": "rule", "text": "Nouns ending in -s, -ss, -sh, -ch or -x add -es (box → boxes, watch → watches, bus → buses)."}, {"type": "rule", "text": "Consonant + y changes to -ies (baby → babies); vowel + y just adds -s (boy → boys)."}, {"type": "rule", "text": "Some nouns are irregular: woman → women, child → children, man → men, foot → feet, sheep → sheep."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1fdf7edf-4e1a-5c1b-a435-64c7168b77c4','e4a8fe05-9a1c-5cff-abf7-4fef0795c027',0,'FILL_BLANK','Напиши форму множественного числа.',$j${"items": [{"before": "one box, two", "after": ""}, {"before": "one sheep, two", "after": ""}, {"before": "one boy, two", "after": ""}, {"before": "one key, two", "after": ""}, {"before": "one umbrella, two", "after": ""}, {"before": "one crocodile, two", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1fdf7edf-4e1a-5c1b-a435-64c7168b77c4',$j${"items": [{"accept": ["boxes"]}, {"accept": ["sheep"]}, {"accept": ["boys"]}, {"accept": ["keys"]}, {"accept": ["umbrellas"]}, {"accept": ["crocodiles"]}]}$j$::jsonb,'');
