INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b117454d-5ca6-56e5-af5a-a8f66bad4061','4de31290-afc0-5aab-b902-ff3ba735bf03','Past Continuous vs Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "The past continuous (was/were + verb-ing) describes an action that was in progress at a particular time in the past."}, {"type": "rule", "text": "The past simple describes a completed action in the past."}, {"type": "rule", "text": "We use the past continuous for a longer action that was interrupted by a shorter action in the past simple; 'when' usually introduces the past simple action. We use 'while' with the past continuous for two actions happening at the same time."}, {"type": "examples", "items": ["Bill was surfing the Net when the doorbell rang.", "John was studying while his mother was cooking dinner.", "Last year, we travelled to India on holiday.", "The baby was sleeping at 10 o'clock this morning."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('32bd8a17-76f2-59d3-8fbc-901b7d322e54','b117454d-5ca6-56e5-af5a-a8f66bad4061',0,'FILL_BLANK','Поставьте глаголы в скобках в past simple или past continuous.',$j${"items": [{"before": "What", "after": "to Alex? (happen)"}, {"before": "He", "after": "football when he fell over. (play)"}, {"before": "He was playing football when he", "after": "over. (fall)"}, {"before": "...and", "after": "his leg. (break)"}, {"before": "", "after": "to hospital? — Yes, he did. (he/go)"}, {"before": "When", "after": "Tony? (you/see)"}, {"before": "While I", "after": "at the bus stop yesterday morning. (wait)"}, {"before": "I", "after": "you last night but you didn't answer. (call)"}, {"before": "I called you last night but you", "after": ". (not/answer)"}, {"before": "I", "after": "at the gym. (exercise)"}, {"before": "What", "after": "when you came home last night? (your kids/do)"}, {"before": "...when you", "after": "home last night? (come)"}, {"before": "They", "after": "a film on television. (watch)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('32bd8a17-76f2-59d3-8fbc-901b7d322e54',$j${"items": [{"accept": ["happened"]}, {"accept": ["was playing"]}, {"accept": ["fell"]}, {"accept": ["broke"]}, {"accept": ["Did he go", "did he go"]}, {"accept": ["did you see"]}, {"accept": ["was waiting"]}, {"accept": ["called"]}, {"accept": ["didn't answer", "did not answer"]}, {"accept": ["was exercising"]}, {"accept": ["were your kids doing"]}, {"accept": ["came"]}, {"accept": ["were watching"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8d381391-dace-566a-a92f-387b65d273f7','b117454d-5ca6-56e5-af5a-a8f66bad4061',1,'CHOOSE','Подчеркните правильный вариант (past simple или past continuous).',$j${"items": [{"before": "Bill", "after": "the Net when the doorbell rang.", "options": [{"id": "o1", "label": "was surfing"}, {"id": "o2", "label": "surfed"}]}, {"before": "Bill was surfing the Net when the doorbell", "after": ".", "options": [{"id": "o1", "label": "was ringing"}, {"id": "o2", "label": "rang"}]}, {"before": "First, Timothy", "after": "out of bed and then he put on his slippers.", "options": [{"id": "o1", "label": "got"}, {"id": "o2", "label": "was getting"}]}, {"before": "Last year, we", "after": "to India on holiday.", "options": [{"id": "o1", "label": "travelled"}, {"id": "o2", "label": "were travelling"}]}, {"before": "At 5 o'clock yesterday afternoon, David and his brother", "after": "their dog a bath.", "options": [{"id": "o1", "label": "were giving"}, {"id": "o2", "label": "gave"}]}, {"before": "John", "after": "while his mother was cooking dinner.", "options": [{"id": "o1", "label": "was studying"}, {"id": "o2", "label": "studied"}]}, {"before": "John was studying while his mother", "after": "dinner.", "options": [{"id": "o1", "label": "was cooking"}, {"id": "o2", "label": "cooked"}]}, {"before": "Claire", "after": "for the bus when she tripped over her shoelaces.", "options": [{"id": "o1", "label": "was running"}, {"id": "o2", "label": "ran"}]}, {"before": "Claire was running for the bus when she", "after": "over her shoelaces.", "options": [{"id": "o1", "label": "was tripping"}, {"id": "o2", "label": "tripped"}]}, {"before": "The students", "after": "carefully while the teacher was speaking.", "options": [{"id": "o1", "label": "listened"}, {"id": "o2", "label": "were listening"}]}, {"before": "The students were listening carefully while the teacher", "after": ".", "options": [{"id": "o1", "label": "spoke"}, {"id": "o2", "label": "was speaking"}]}, {"before": "The baby", "after": "at 10 o'clock this morning.", "options": [{"id": "o1", "label": "was sleeping"}, {"id": "o2", "label": "slept"}]}]}$j$::jsonb,10);
