INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2d07e720-7334-59de-99d3-6e6d78ed802c','b117454d-5ca6-56e5-af5a-a8f66bad4061',2,'MATCH_PAIRS','Прочитайте текст ''The Riddle of the Sphinx'' и соотнесите выделенные фразы с их значением.',$j${"left": [{"id": "l1", "label": "was travelling through Greece"}, {"id": "l2", "label": "was entering the city when the Sphinx stopped him"}, {"id": "l3", "label": "While Oedipus was thinking, the Sphinx was laughing"}, {"id": "l4", "label": "she jumped off her rock, fell to the ground, and died"}, {"id": "l5", "label": "made Oedipus their king"}], "right": [{"id": "r1", "label": "a completed action in the past"}, {"id": "r2", "label": "actions which happened immediately one after the other in the past"}, {"id": "r3", "label": "an action that was happening at a particular time in the past"}, {"id": "r4", "label": "actions happening at the same time in the past"}, {"id": "r5", "label": "a past action that was in progress when another action interrupted it"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2d07e720-7334-59de-99d3-6e6d78ed802c',$j${"pairs": [{"l": "l1", "r": "r3"}, {"l": "l2", "r": "r5"}, {"l": "l3", "r": "r4"}, {"l": "l4", "r": "r2"}, {"l": "l5", "r": "r1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('499aa7f1-7b03-521a-8391-6476ba8759b0','b117454d-5ca6-56e5-af5a-a8f66bad4061',3,'FILL_BLANK','Поставьте глаголы в скобках в past simple или past continuous.',$j${"items": [{"before": "Last year we", "after": "to Germany on holiday. (travel)"}, {"before": "Anna", "after": "tea at four o'clock yesterday afternoon. (drink)"}, {"before": "Jane", "after": "while her brother listened to music. (study)"}, {"before": "Jane was studying while her brother", "after": "to music. (listen)"}, {"before": "Sam", "after": "the dog when it bit him. (pat)"}, {"before": "Sam was patting the dog when it", "after": "him. (bite)"}, {"before": "What", "after": "when the fire started? (you/do)"}]}$j$::jsonb,10);
