INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4216c0ee-66df-590f-b49b-a906e401597a','3d69ee65-1d7d-573c-8ecd-35bae74cf2ed','this / these - that / those',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'this' (singular) and 'these' (plural) for things that are near us."}, {"type": "rule", "text": "We use 'that' (singular) and 'those' (plural) for things that are far from us."}, {"type": "examples", "items": ["This is a guitar.", "These are pencils.", "That is a bus over there.", "Those are birds in the sky."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f4d75b23-e870-525e-adf4-d198480b67d6','4216c0ee-66df-590f-b49b-a906e401597a',0,'CHOOSE','Выбери ''this'' или ''these'' (предмет рядом).',$j${"items": [{"before": "", "after": "is a guitar.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}]}, {"before": "", "after": "are pencils.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}]}, {"before": "", "after": "is a house.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}]}, {"before": "", "after": "are towels.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}]}]}$j$::jsonb,10);
