INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c274c478-0244-5919-9890-423d6cc8f452','4216c0ee-66df-590f-b49b-a906e401597a',1,'CHOOSE','Выбери ''that'' или ''those'' (предмет далеко).',$j${"items": [{"before": "Look at", "after": "birds over there.", "options": [{"id": "o1", "label": "that"}, {"id": "o2", "label": "those"}]}, {"before": "", "after": "mountain in the distance is high.", "options": [{"id": "o1", "label": "That"}, {"id": "o2", "label": "Those"}]}, {"before": "Who is", "after": "man near the door?", "options": [{"id": "o1", "label": "that"}, {"id": "o2", "label": "those"}]}]}$j$::jsonb,10);
