INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('460127f1-26f9-55b4-aedc-6c0226b62d67','a0000000-0000-4000-8000-0000000000a2','Блок 6. Conditionals',6,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c2ecc3e6-0e61-59b6-b947-f0c3f69b547d','460127f1-26f9-55b4-aedc-6c0226b62d67','Conditionals',0,'LESSON',70,$j$[{"type": "rule", "text": "Type 1 Conditional (real / likely): If + Present Simple, ... will + infinitive. We use it for real or possible situations in the present or future."}, {"type": "rule", "text": "Type 2 Conditional (unreal / imaginary): If + Past Simple, ... would + infinitive. We use it for imaginary or unlikely situations."}, {"type": "rule", "text": "'Unless' means 'if not' and is followed by an affirmative verb."}, {"type": "examples", "items": ["If it rains tomorrow, we will stay at home.", "If I were rich, I would travel the world.", "Unless you hurry, you will miss the bus."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5c109d58-8de5-5e2d-8da6-9ce369a8baf0','c2ecc3e6-0e61-59b6-b947-f0c3f69b547d',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "Does Robbie work at the bank? No, he", "after": ".", "options": [{"id": "o1", "label": "don't"}, {"id": "o2", "label": "isn't"}, {"id": "o3", "label": "doesn't"}]}, {"before": "This is my pen and", "after": "are my pencils.", "options": [{"id": "o1", "label": "those"}, {"id": "o2", "label": "this"}, {"id": "o3", "label": "that"}]}, {"before": "Is she", "after": "actress?", "options": [{"id": "o1", "label": "an"}, {"id": "o2", "label": "-"}, {"id": "o3", "label": "a"}]}, {"before": "Janet", "after": "Chinese food.", "options": [{"id": "o1", "label": "likes"}, {"id": "o2", "label": "is liking"}, {"id": "o3", "label": "like"}]}, {"before": "If I", "after": "you, I wouldn't drink so much coffee.", "options": [{"id": "o1", "label": "be"}, {"id": "o2", "label": "am"}, {"id": "o3", "label": "were"}]}, {"before": "What is", "after": "job? He's a firefighter.", "options": [{"id": "o1", "label": "he"}, {"id": "o2", "label": "him"}, {"id": "o3", "label": "his"}]}, {"before": "I love dogs. They are", "after": "favourite animal.", "options": [{"id": "o1", "label": "our"}, {"id": "o2", "label": "your"}, {"id": "o3", "label": "my"}]}, {"before": "She usually", "after": "her homework in the evenings.", "options": [{"id": "o1", "label": "do"}, {"id": "o2", "label": "does"}, {"id": "o3", "label": "doing"}]}, {"before": "Linda", "after": "gets up early every day because she starts work at 7 o'clock.", "options": [{"id": "o1", "label": "never"}, {"id": "o2", "label": "always"}, {"id": "o3", "label": "sometimes"}]}, {"before": "Emma was doing the washing up while I", "after": "the floor.", "options": [{"id": "o1", "label": "mopped"}, {"id": "o2", "label": "mop"}, {"id": "o3", "label": "was mopping"}]}, {"before": "Where is Kate? She", "after": "around Europe at the moment.", "options": [{"id": "o1", "label": "travel"}, {"id": "o2", "label": "travels"}, {"id": "o3", "label": "is travelling"}]}, {"before": "Scientists believe that people", "after": "electric cars in the future.", "options": [{"id": "o1", "label": "will use"}, {"id": "o2", "label": "are using"}, {"id": "o3", "label": "use"}]}, {"before": "They rarely visit their grandparents,", "after": "they?", "options": [{"id": "o1", "label": "don't"}, {"id": "o2", "label": "do"}, {"id": "o3", "label": "does"}]}, {"before": "Unless Nick", "after": "early, he won't catch the train.", "options": [{"id": "o1", "label": "leaves"}, {"id": "o2", "label": "is leaving"}, {"id": "o3", "label": "doesn't leave"}]}, {"before": "What", "after": "you doing last night at 8 o'clock?", "options": [{"id": "o1", "label": "are"}, {"id": "o2", "label": "was"}, {"id": "o3", "label": "were"}]}, {"before": "I", "after": "down the street when I saw my friend.", "options": [{"id": "o1", "label": "walked"}, {"id": "o2", "label": "is walking"}, {"id": "o3", "label": "was walking"}]}, {"before": "Adam", "after": "to India tonight.", "options": [{"id": "o1", "label": "is flying"}, {"id": "o2", "label": "flies"}, {"id": "o3", "label": "fly"}]}, {"before": "You've got a bad cold. I", "after": "you some soup.", "options": [{"id": "o1", "label": "make"}, {"id": "o2", "label": "makes"}, {"id": "o3", "label": "will make"}]}, {"before": "If you help me with the dishes, I", "after": "you with your homework.", "options": [{"id": "o1", "label": "will help"}, {"id": "o2", "label": "am helping"}, {"id": "o3", "label": "help"}]}, {"before": "I think Harriet", "after": "come to the meeting.", "options": [{"id": "o1", "label": "isn't"}, {"id": "o2", "label": "doesn't"}, {"id": "o3", "label": "won't"}]}, {"before": "If I don't study hard, I", "after": "my exams.", "options": [{"id": "o1", "label": "will pass"}, {"id": "o2", "label": "won't pass"}, {"id": "o3", "label": "don't pass"}]}, {"before": "Emma", "after": "be able to help us if she was here.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "would"}, {"id": "o3", "label": "won't"}]}, {"before": "If I", "after": "some money, I will buy a nice house.", "options": [{"id": "o1", "label": "will win"}, {"id": "o2", "label": "is winning"}, {"id": "o3", "label": "win"}]}, {"before": "William", "after": "to be a firefighter.", "options": [{"id": "o1", "label": "used"}, {"id": "o2", "label": "would"}, {"id": "o3", "label": "use"}]}, {"before": "Jane was sleeping when I", "after": "her.", "options": [{"id": "o1", "label": "called"}, {"id": "o2", "label": "was calling"}, {"id": "o3", "label": "is calling"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5c109d58-8de5-5e2d-8da6-9ce369a8baf0',$j${"items": [{"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o3"}, {"correctId": "o3"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o3"}, {"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('78edd56f-9efc-501b-a751-1d0a8bbaebb5','a0000000-0000-4000-8000-0000000000a2','Блок 7. Adverbs, Comparatives & too/enough',7,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2981647d-834f-5c81-b274-83de76f5c11a','78edd56f-9efc-501b-a751-1d0a8bbaebb5','Adverbs, Comparatives & too/enough',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of manner tell us how something happens and are usually formed by adding -ly to an adjective (quick -> quickly)."}, {"type": "rule", "text": "Some words have the same form as adjective and adverb: fast, hard, early, late."}, {"type": "rule", "text": "After verbs like look, sound, feel, taste and smell we use an adjective, not an adverb (It looks peaceful.)."}, {"type": "rule", "text": "Comparative: short adjective + -er + than, or more + long adjective + than. Superlative: the + adjective + -est, or the most + adjective."}, {"type": "rule", "text": "'too + adjective' means more than necessary (negative). 'adjective + enough' means as much as necessary. 'not ... enough' means less than necessary. Both are followed by a to-infinitive."}, {"type": "rule", "text": "'(not) as + adjective + as' shows that two people or things are (not) similar. 'less + adjective + of/in' shows inferiority."}, {"type": "examples", "items": ["She speaks English fluently.", "This car is faster than that one.", "It's too cold to swim in the sea.", "He isn't old enough to drive.", "Anna is as tall as her brother."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('28e88fd3-93c1-5c37-95cc-ae70a44a8e5a','2981647d-834f-5c81-b274-83de76f5c11a',0,'SORT_COLUMNS','Распределите слова по колонкам: как / где / когда / как часто.',$j${"columns": [{"id": "c1", "label": "how"}, {"id": "c2", "label": "where"}, {"id": "c3", "label": "when"}, {"id": "c4", "label": "how often"}], "items": [{"id": "i1", "label": "happily"}, {"id": "i2", "label": "yesterday"}, {"id": "i3", "label": "never"}, {"id": "i4", "label": "there"}, {"id": "i5", "label": "wonderfully"}, {"id": "i6", "label": "quickly"}, {"id": "i7", "label": "sometimes"}, {"id": "i8", "label": "always"}, {"id": "i9", "label": "last month"}, {"id": "i10", "label": "fast"}, {"id": "i11", "label": "loudly"}, {"id": "i12", "label": "early"}, {"id": "i13", "label": "by taxi"}, {"id": "i14", "label": "to the beach"}, {"id": "i15", "label": "angrily"}, {"id": "i16", "label": "usually"}, {"id": "i17", "label": "here"}, {"id": "i18", "label": "to the park"}]}$j$::jsonb,10);
