INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('303d9732-a66e-5154-a39b-5b7ab1c174d0','2981647d-834f-5c81-b274-83de76f5c11a',1,'CHOOSE','Подчеркните (выберите) правильное слово.',$j${"items": [{"before": "They were dancing", "after": "to the music.", "options": [{"id": "o1", "label": "happy"}, {"id": "o2", "label": "happily"}]}, {"before": "He is a very", "after": "driver.", "options": [{"id": "o1", "label": "careful"}, {"id": "o2", "label": "carefully"}]}, {"before": "Jane ran", "after": "to the bus stop.", "options": [{"id": "o1", "label": "quick"}, {"id": "o2", "label": "quickly"}]}, {"before": "She sounded very", "after": "on the phone.", "options": [{"id": "o1", "label": "angry"}, {"id": "o2", "label": "angrily"}]}, {"before": "The village looked", "after": ".", "options": [{"id": "o1", "label": "peaceful"}, {"id": "o2", "label": "peacefully"}]}, {"before": "The test was", "after": ".", "options": [{"id": "o1", "label": "easy"}, {"id": "o2", "label": "easily"}]}, {"before": "Ann's in a", "after": "mood today.", "options": [{"id": "o1", "label": "bad"}, {"id": "o2", "label": "badly"}]}, {"before": "She dances", "after": ".", "options": [{"id": "o1", "label": "beautiful"}, {"id": "o2", "label": "beautifully"}]}, {"before": "I", "after": "can't do this.", "options": [{"id": "o1", "label": "simple"}, {"id": "o2", "label": "simply"}]}, {"before": "She spoke in a", "after": "voice.", "options": [{"id": "o1", "label": "soft"}, {"id": "o2", "label": "softly"}]}]}$j$::jsonb,10);
