INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b60278d6-4586-506a-b9e1-235000b2588a','2981647d-834f-5c81-b274-83de76f5c11a',10,'FILL_BLANK','Дополните предложения словами из списка (careful(ly), terrible(ly), fluent(ly), possible(ly), total(ly), happy(ily), sad(ly), heavy(ily), safe(ly), sudden(ly)) в правильной форме.',$j${"items": [{"before": "When the teacher came into the classroom there was", "after": "silence."}, {"before": "Sara can speak French", "after": "."}, {"before": "Fred and Mary were", "after": "married for over 46 years."}, {"before": "Berk sighed", "after": "when he saw how much walking he had to do."}, {"before": "Brian is a very", "after": "driver."}, {"before": "We made it home", "after": "and sound."}, {"before": "", "after": "there was a loud bang from upstairs."}, {"before": "He tried every", "after": "solution but nothing worked."}, {"before": "When he went away to university, Tom missed his family", "after": "."}, {"before": "Titanic is a very", "after": "film."}]}$j$::jsonb,10);
