INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4fd2592a-daa9-545c-8a3d-5351ef05a634','2981647d-834f-5c81-b274-83de76f5c11a',11,'FILL_BLANK','Дополните предложения словом too или enough.',$j${"items": [{"before": "It's", "after": "noisy in here. I can't do my homework."}, {"before": "I'm sorry but I can't meet you for lunch today, I'm", "after": "busy."}, {"before": "My little sister isn't tall", "after": "to reach the top shelf."}, {"before": "The kitten won't come near us. It's", "after": "scared."}, {"before": "I haven't got", "after": "flour to make a cake."}, {"before": "My dad says that when I'm old", "after": "to drive, he'll buy me a car."}, {"before": "There isn't", "after": "room in the car for seven people."}, {"before": "She isn't old", "after": "to get married."}]}$j$::jsonb,10);
