INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('75fb1f9e-cf36-50f2-b3a6-794e80846f36','2981647d-834f-5c81-b274-83de76f5c11a',12,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "Did Bill", "after": "out with you last night?", "options": [{"id": "o1", "label": "come"}, {"id": "o2", "label": "comes"}, {"id": "o3", "label": "came"}]}, {"before": "I think 'The Independent' is the", "after": "newspaper in the UK.", "options": [{"id": "o1", "label": "good"}, {"id": "o2", "label": "better"}, {"id": "o3", "label": "best"}]}, {"before": "Last night at 6 pm they", "after": "dinner.", "options": [{"id": "o1", "label": "ate"}, {"id": "o2", "label": "are eating"}, {"id": "o3", "label": "were eating"}]}, {"before": "There are a lot of", "after": "in that field.", "options": [{"id": "o1", "label": "sheep"}, {"id": "o2", "label": "sheeps"}, {"id": "o3", "label": "sheep's"}]}, {"before": "Today is hotter", "after": "yesterday.", "options": [{"id": "o1", "label": "from"}, {"id": "o2", "label": "of"}, {"id": "o3", "label": "than"}]}, {"before": "James", "after": "having a shower when the phone rang.", "options": [{"id": "o1", "label": "were"}, {"id": "o2", "label": "is"}, {"id": "o3", "label": "was"}]}, {"before": "She is tired,", "after": "she?", "options": [{"id": "o1", "label": "doesn't"}, {"id": "o2", "label": "isn't"}, {"id": "o3", "label": "is"}]}, {"before": "Is Sasha", "after": "at her desk now?", "options": [{"id": "o1", "label": "work"}, {"id": "o2", "label": "working"}, {"id": "o3", "label": "works"}]}, {"before": "If you", "after": "to Paris, you will see the Eiffel Tower.", "options": [{"id": "o1", "label": "will go"}, {"id": "o2", "label": "go"}, {"id": "o3", "label": "goes"}]}, {"before": "Helen isn't as", "after": "as her sister.", "options": [{"id": "o1", "label": "taller"}, {"id": "o2", "label": "tallest"}, {"id": "o3", "label": "tall"}]}, {"before": "That looks heavy. I", "after": "you.", "options": [{"id": "o1", "label": "is helping"}, {"id": "o2", "label": "help"}, {"id": "o3", "label": "'ll help"}]}, {"before": "Tracey is", "after": "thinner than Laura.", "options": [{"id": "o1", "label": "less"}, {"id": "o2", "label": "very"}, {"id": "o3", "label": "much"}]}, {"before": "They", "after": "to the supermarket every Saturday.", "options": [{"id": "o1", "label": "go"}, {"id": "o2", "label": "goes"}, {"id": "o3", "label": "are going"}]}, {"before": "I", "after": "up very late yesterday.", "options": [{"id": "o1", "label": "wakes"}, {"id": "o2", "label": "wake"}, {"id": "o3", "label": "woke"}]}, {"before": "Unless you", "after": ", you will fail the test.", "options": [{"id": "o1", "label": "don't study"}, {"id": "o2", "label": "study"}, {"id": "o3", "label": "studies"}]}, {"before": "Kathy is the smartest student", "after": "all.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "from"}, {"id": "o3", "label": "of"}]}, {"before": "Lisa didn't", "after": "play sports when she was a child.", "options": [{"id": "o1", "label": "used to"}, {"id": "o2", "label": "use to"}, {"id": "o3", "label": "use"}]}, {"before": "", "after": "they got a CD player?", "options": [{"id": "o1", "label": "Has"}, {"id": "o2", "label": "Have"}, {"id": "o3", "label": "Hasn't"}]}, {"before": "If I", "after": "money, I would go on holiday.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}, {"id": "o3", "label": "had"}]}, {"before": "Are the", "after": "ready to leave?", "options": [{"id": "o1", "label": "children's"}, {"id": "o2", "label": "childrens"}, {"id": "o3", "label": "children"}]}, {"before": "Where", "after": "you go on holiday last summer?", "options": [{"id": "o1", "label": "did"}, {"id": "o2", "label": "do"}, {"id": "o3", "label": "were"}]}, {"before": "Nancy was washing the dishes while Tom", "after": "reading the newspaper.", "options": [{"id": "o1", "label": "were"}, {"id": "o2", "label": "is"}, {"id": "o3", "label": "was"}]}, {"before": "How", "