INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('afc8f422-d0a0-540f-9903-8232963fb14c','a0000000-0000-4000-8000-0000000000a2','Блок 8. Present Perfect',8,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3d72fde3-f4b8-554a-91ed-db03170191cf','afc8f422-d0a0-540f-9903-8232963fb14c','Present Perfect',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Present Perfect for actions that happened at an unstated time in the past, for experiences, for recent actions with a result in the present, and for actions that started in the past and continue to the present."}, {"type": "rule", "text": "We form the Present Perfect with have/has + past participle. Negative: haven't/hasn't + past participle. Question: Have/Has + subject + past participle?"}, {"type": "text", "text": "We often use the Present Perfect with the time expressions: ever, never, just, already, yet, so far, for, since and this week."}, {"type": "examples", "items": ["I have lost my keys, so I can't get in.", "She has been a teacher since 1999.", "They haven't arrived yet.", "Have you ever been to the Louvre?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('62549804-c26e-5107-bbb0-dd47d85e9867','3d72fde3-f4b8-554a-91ed-db03170191cf',0,'MCQ','Прочитайте предложение и выберите правильное значение.',$j${"question": "\"I've lost my book.\" What does this mean?", "options": [{"id": "a", "label": "I haven't got it now."}, {"id": "b", "label": "I didn't have it in the past but I have it now."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('62549804-c26e-5107-bbb0-dd47d85e9867',$j${"correctId": "a"}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('eaca05ea-9790-5fba-bcda-b749cc3de7a5','3d72fde3-f4b8-554a-91ed-db03170191cf',1,'MCQ','Прочитайте предложение и выберите правильное значение.',$j${"question": "\"She has been a teacher since 1999.\" What does this mean?", "options": [{"id": "a", "label": "She isn't a teacher anymore."}, {"id": "b", "label": "She is still a teacher."}]}$j$::jsonb,10);
