INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('861a66c3-fc85-59d5-a313-55a9cbd4dd6d','3d72fde3-f4b8-554a-91ed-db03170191cf',6,'FILL_BLANK','Поставьте глаголы в скобках в правильную форму Present Perfect.',$j${"items": [{"before": "A: Did you like the film Star Wars? B: I don't know. I (never/see)", "after": "it."}, {"before": "A: Do you know Henry? B: Yes, I (meet)", "after": "him once before."}, {"before": "A: What time does the plane take off? B: It (just/take off)", "after": "."}, {"before": "A: Did Sally like these biscuits? B: She (not/taste)", "after": "them yet."}, {"before": "A: How's Philip? B: I don't know. I (not/speak)", "after": "to him since Tuesday."}, {"before": "A: Can I read your magazine? B: Sorry! I (not/finish)", "after": "with it yet."}]}$j$::jsonb,10);
