INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d088cc5b-0681-5b58-bd7e-c9e829c6cca1','3d72fde3-f4b8-554a-91ed-db03170191cf',7,'CHOOSE','Выберите for или since.',$j${"items": [{"before": "He hasn't come to school", "after": "a week.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "Jenny has been a nurse", "after": "1995.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "We have lived in Canada", "after": "ten years.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "He has been in Cairo", "after": "Friday.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "She hasn't bought anything new", "after": "December.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "They haven't visited their grandparents", "after": "last week.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "I haven't travelled abroad", "after": "last summer.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "He hasn't heard from Emily", "after": "a long time.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "They haven't had dinner at a restaurant", "after": "ages.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}, {"before": "We have been at work", "after": "8 o'clock.", "options": [{"id": "o1", "label": "for"}, {"id": "o2", "label": "since"}]}]}$j$::jsonb,10);
