INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4c97148d-c73f-524f-af60-5490339d6ea2','3d72fde3-f4b8-554a-91ed-db03170191cf',8,'FILL_BLANK','Впишите правильное слово из рамки: just, since, for, this week, ever, never, yet, so far.',$j${"items": [{"before": "She's played in two international competitions", "after": "."}, {"before": "William has been ill", "after": "Sunday."}, {"before": "We have been to the theatre twice", "after": "."}, {"before": "I have", "after": "finished my report. I finished it five minutes ago."}, {"before": "Betty and Julie have been friends", "after": "many years."}, {"before": "I haven't been to the new shopping centre", "after": ". I think I'll go sometime next week."}, {"before": "This is the most beautiful place I have", "after": "seen."}, {"before": "I have", "after": "been to China. I hope I'll go some day."}]}$j$::jsonb,10);
