INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('0063a4bc-9ea6-5435-ab19-62abdb9104fd','a0000000-0000-4000-8000-0000000000a2','Блок 9. Present Perfect vs Past Simple',9,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3ba44a31-6e89-5675-a5c9-4676c9cd4db3','0063a4bc-9ea6-5435-ab19-62abdb9104fd','Present Perfect vs Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Past Simple for actions that happened at a stated (definite) time in the past, e.g. yesterday, last week, two days ago, in 2005."}, {"type": "rule", "text": "We use the Present Perfect for actions at an unstated time, for experiences, for recent actions with a present result, and for actions that started in the past and still continue."}, {"type": "examples", "items": ["I went to Paris last summer. (Past Simple - stated time)", "I have been to Paris. (Present Perfect - experience)", "She has just broken her leg, so she can't walk.", "He worked here from 2000 to 2005, but he has worked in London since 2006."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a5758288-8424-55d8-a6aa-31741456ada8','3ba44a31-6e89-5675-a5c9-4676c9cd4db3',0,'FILL_BLANK','Поставьте глаголы в скобках в Present Perfect или Past Simple.',$j${"items": [{"before": "Sam: Hi Jesse! Where (you/be)", "after": "?"}, {"before": "Sam: I (not/see)", "after": "you for ages!"}, {"before": "Jesse: I know. I'm sorry. I (be)", "after": "really busy recently."}, {"before": "Jesse: And guess what! Last week, I (sit)", "after": "my driving test"}, {"before": "Jesse: and I (pass)", "after": "! I have my licence now!"}, {"before": "Jesse: Yes. I (already/start)", "after": "to look for one."}, {"before": "Jesse: I (not/find)", "after": "anything yet though."}, {"before": "Sam: When I (buy)", "after": "my car last year,"}, {"before": "Sam: I (find)", "after": "some good car dealerships."}]}$j$::jsonb,10);
