INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b5404e19-a5c2-5363-8d9e-2dfadf82dc3d','3ba44a31-6e89-5675-a5c9-4676c9cd4db3',1,'FILL_BLANK','Поставьте глаголы в скобках в Present Perfect или Past Simple (письмо).',$j${"items": [{"before": "We (arrive)", "after": "two days ago"}, {"before": "but I (already/injure)", "after": "myself!"}, {"before": "Yesterday, we (go)", "after": "mountain climbing."}, {"before": "We (decide)", "after": "to go up a very steep path"}, {"before": "but it (be)", "after": "full of rocks."}, {"before": "I (slip)", "after": "on one,"}, {"before": "and (fall)", "after": ""}, {"before": "and (break)", "after": "my leg."}, {"before": "It (not/hurt)", "after": "much at first"}, {"before": "Tony (take)", "after": "me to the hospital"}, {"before": "and the doctor (put)", "after": "a cast on my leg."}, {"before": "(you/decide)", "after": "where you are going on holiday yet?"}]}$j$::jsonb,10);
