INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a519becc-0f57-53db-908d-4de958c81213','a0000000-0000-4000-8000-0000000000a2','Блок 11. A few / few / a little / little',11,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8ee48839-2d69-5740-b441-9c38c20fb0db','a519becc-0f57-53db-908d-4de958c81213','A few / few / a little / little',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'a few' and 'few' with countable plural nouns, and 'a little' and 'little' with uncountable nouns."}, {"type": "rule", "text": "'a few' and 'a little' have a positive meaning (= some, a small amount). 'few' and 'little' have a negative meaning (= not much / not many, almost none)."}, {"type": "examples", "items": ["There are a few biscuits left, so you can have one.", "Few people came to the meeting, so it was cancelled.", "I have a little money, so I can buy a coffee.", "There is little milk in the fridge, so we can't make pancakes."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cc858a2c-8dad-5ae3-aab6-5e441f59d94e','8ee48839-2d69-5740-b441-9c38c20fb0db',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "I have", "after": "friends in this city, so I'm never lonely.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "There is", "after": "milk in the fridge; we need to buy more.", "options": [{"id": "o1", "label": "little"}, {"id": "o2", "label": "few"}]}, {"before": "She has", "after": "money, so she can't buy the dress.", "options": [{"id": "o1", "label": "little"}, {"id": "o2", "label": "a little"}]}, {"before": "Add", "after": "salt to the soup, please.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "", "after": "people came to the party because of the rain.", "options": [{"id": "o1", "label": "Few"}, {"id": "o2", "label": "Little"}]}, {"before": "We still have", "after": "time before the train leaves.", "options": [{"id": "o1", "label": "a little"}, {"id": "o2", "label": "a few"}]}, {"before": "There are", "after": "eggs left; enough for an omelette.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "He speaks", "after": "English, so it's hard to understand him.", "options": [{"id": "o1", "label": "little"}, {"id": "o2", "label": "few"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('cc858a2c-8dad-5ae3-aab6-5e441f59d94e',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
