INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('4b8b1f11-cf57-5b23-a4e6-6d8c9c17b1cc','a0000000-0000-4000-8000-0000000000a2','Блок 13. Relative Clauses (who / which / whose / that)',13,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c','4b8b1f11-cf57-5b23-a4e6-6d8c9c17b1cc','Relative Clauses (who / which / whose / that)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'who' or 'that' for people, 'which' or 'that' for things/animals, and 'whose' to show possession (whose = someone's)."}, {"type": "rule", "text": "Defining relative clauses give essential information and take no commas: The man who lives next door is a doctor. Non-defining relative clauses give extra information, take commas and cannot use 'that': Mrs Smith, who is a nurse, lives next door."}, {"type": "examples", "items": ["Thomas Edison is the man who invented the light bulb.", "This is the car which I want to buy.", "I met a boy whose name is Robbie."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3500c592-2083-599d-846e-38ec1c82dc49','42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c',0,'MATCH_PAIRS','Соедините части, чтобы получились правильные предложения.',$j${"left": [{"id": "l1", "label": "This is the car"}, {"id": "l2", "label": "Thomas Edison is the man"}, {"id": "l3", "label": "Is this the DVD"}, {"id": "l4", "label": "The nurse"}, {"id": "l5", "label": "Elvis Presley"}, {"id": "l6", "label": "The report"}, {"id": "l7", "label": "I met a boy"}, {"id": "l8", "label": "Is she the woman"}], "right": [{"id": "r1", "label": "who invented the light bulb."}, {"id": "r2", "label": "I want to buy."}, {"id": "r3", "label": "who won the lottery?"}, {"id": "r4", "label": "which you wrote was very interesting."}, {"id": "r5", "label": "whose name is Robbie."}, {"id": "r6", "label": "who looked after my grandmother was very kind."}, {"id": "r7", "label": "whose songs were very popular, died in 1977."}, {"id": "r8", "label": "which your friend gave you?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3500c592-2083-599d-846e-38ec1c82dc49',$j${"pairs": [{"l": "l1", "r": "r2"}, {"l": "l2", "r": "r1"}, {"l": "l3", "r": "r8"}, {"l": "l4", "r": "r6"}, {"l": "l5", "r": "r7"}, {"l": "l6", "r": "r4"}, {"l": "l7", "r": "r5"}, {"l": "l8", "r": "r3"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('89248f0d-af0e-5adf-adda-3f496db373b5','42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c',1,'FILL_BLANK','Вставьте относительное местоимение (who, which, whose или that).',$j${"items": [{"before": "Mrs Smith,", "after": "lives next door, is a nurse."}, {"before": "That's the girl", "after": "sits next to me at school."}, {"before": "That house", "after": "is very big belongs to my grandparents."}, {"before": "Have you seen that new film", "after": "stars Nicole Kidman?"}, {"before": "I know a girl", "after": "brother is a singer."}, {"before": "This ring,", "after": "is very old, belonged to my grandma."}, {"before": "The book", "after": "was advertised on TV was very interesting."}, {"before": "Gillian,", "after": "is only 20 years old, got married last month."}, {"before": "The bag", "after": "you bought last week is beautiful."}, {"before": "The film", "after": "we watched last night was terrible."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('89248f0d-af0e-5adf-adda-3f496db373b5',$j${"items": [{"accept": ["who"]}, {"accept": ["who", "that"]}, {"accept": ["which", "that"]}, {"accept": ["which", "that"]}, {"accept": ["whose"]}, {"accept": ["which"]}, {"accept": ["which", "that"]}, {"accept": ["who"]}, {"accept": ["which", "that"]}, {"accept": ["which", "that"]}]}$j$::jsonb,'');
