INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7f7b8044-8e14-5439-9626-1bc021c75bc0','42af2fc5-3b08-592d-a6ab-9d45b4bdcc7c',3,'SHORT_TEXT','Объедините два предложения в одно, используя относительное местоимение: ''This is Helen. She teaches us French.''',$j${"question": "This is Helen. She teaches us French."}$j$::jsonb,10);
