INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('30caa025-a2d4-5a6a-90c9-2d4416bf5d90','a0000000-0000-4000-8000-0000000000a2','Блок 14. The Passive (Present & Past Simple)',14,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('98369d51-e207-5e18-b010-21a30501b2c2','30caa025-a2d4-5a6a-90c9-2d4416bf5d90','The Passive (Present & Past Simple)',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the passive with the verb 'to be' (is/are for present, was/were for past) + the past participle of the main verb: Chevrolet cars are made in America. The TV was invented in 1926."}, {"type": "rule", "text": "We use the passive when the person who does the action is unknown or unimportant. We add the doer with 'by' + agent only when it is important: 'Anthony and Cleopatra' was written by Shakespeare."}, {"type": "examples", "items": ["The museum is visited by thousands of tourists every year.", "The building was destroyed by a fire last year.", "The offices are cleaned twice a week."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('504839aa-2466-537b-a8a1-19de55379937','98369d51-e207-5e18-b010-21a30501b2c2',0,'CHOOSE','Выберите правильную форму глагола to be: is, are, was или were.',$j${"items": [{"before": "'Anthony and Cleopatra'", "after": "written by Shakespeare.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "A talent show competition", "after": "organised by our school every year.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "Chevrolet cars", "after": "made in America.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "A documentary on dinosaurs", "after": "shown on TV last Saturday.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "We", "after": "invited to a barbecue last week.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "The Olympics", "after": "held every four years.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "The museum", "after": "visited by thousands of tourists every year.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "The building", "after": "destroyed by a fire last year.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "The offices", "after": "cleaned twice a week.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}, {"before": "The TV", "after": "invented by John Baird in 1926.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}, {"id": "o3", "label": "was"}, {"id": "o4", "label": "were"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('504839aa-2466-537b-a8a1-19de55379937',$j${"items": [{"correctId": "o3"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o3"}, {"correctId": "o4"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o2"}, {"correctId": "o3"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e49818c9-92c4-581b-9802-d2f2252fd36d','98369d51-e207-5e18-b010-21a30501b2c2',1,'FILL_BLANK','Как снимают фильмы? Заполните пропуски формой Present Simple Passive (is/are + Past Participle).',$j${"items": [{"before": "The script", "after": "by a screenwriter."}, {"before": "The script", "after": "by a film producer."}, {"before": "The film", "after": "by a director."}, {"before": "The characters", "after": "by actors."}, {"before": "The scenes", "after": "by a cameraman."}, {"before": "The motion picture", "after": "by the film company."}, {"before": "The film", "after": "in cinemas."}]}$j$::jsonb,10);
