INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('bd52f5e6-dd10-551d-bc43-d8c5ce550940','a0000000-0000-4000-8000-0000000000a2','Блок 15. Future Forms (will / be going to / present continuous)',15,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('2f691974-0d66-56ce-9253-b9fc54e98fb4','bd52f5e6-dd10-551d-bc43-d8c5ce550940','Future Forms (will / be going to / present continuous)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'will' for on-the-spot decisions, promises, offers and predictions we are not sure about: I'll help you. I think it will rain."}, {"type": "rule", "text": "We use 'be going to' for plans and intentions, and for predictions based on what we can see now: Look at those clouds! It's going to rain."}, {"type": "rule", "text": "We use the present continuous for fixed future arrangements, usually with a time expression: I'm meeting my friends after school today."}, {"type": "examples", "items": ["The phone is ringing. I'll answer it.", "They're going to get married next June.", "We're having a party on Saturday evening."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8ddef59c-5597-51ea-9e49-a34086ce32bc','2f691974-0d66-56ce-9253-b9fc54e98fb4',0,'CHOOSE','Выберите правильную форму будущего времени: will или be going to.',$j${"items": [{"before": "Look at those dark clouds!", "after": "", "options": [{"id": "o1", "label": "It will rain."}, {"id": "o2", "label": "It's going to rain."}]}, {"before": "'I'm cold.'", "after": "", "options": [{"id": "o1", "label": "'I'll close the window.'"}, {"id": "o2", "label": "'I'm going to close the window.'"}]}, {"before": "They've booked the church. They", "after": "get married next June.", "options": [{"id": "o1", "label": "are going to"}, {"id": "o2", "label": "will"}]}, {"before": "I think our team", "after": "win the match tomorrow.", "options": [{"id": "o1", "label": "is going to"}, {"id": "o2", "label": "will"}]}, {"before": "'Have you decided?' 'Yes, I", "after": "buy the red one.'", "options": [{"id": "o1", "label": "am going to"}, {"id": "o2", "label": "will"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8ddef59c-5597-51ea-9e49-a34086ce32bc',$j${"items": [{"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5adac167-4bf9-59c6-b652-4dfa67418dc8','2f691974-0d66-56ce-9253-b9fc54e98fb4',1,'FILL_BLANK','Заполните пропуски глаголом в present continuous для запланированных действий в будущем.',$j${"items": [{"before": "I", "after": "(meet) my friends after school today."}, {"before": "She", "after": "(fly) to Paris next Monday."}, {"before": "We", "after": "(have) a party on Saturday evening."}, {"before": "They", "after": "(visit) their grandparents this weekend."}]}$j$::jsonb,10);
