INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7ad9ab61-7727-516d-95f7-c8019543f3a7','2f691974-0d66-56ce-9253-b9fc54e98fb4',2,'CHOOSE','Выберите правильную форму будущего времени.',$j${"items": [{"before": "'The phone is ringing.' 'I", "after": "answer it.'", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}, {"before": "Look at the sky. It", "after": "snow.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "is going to"}]}, {"before": "I", "after": "the dentist at 3 o'clock tomorrow.", "options": [{"id": "o1", "label": "will see"}, {"id": "o2", "label": "am seeing"}]}, {"before": "Maybe it", "after": "sunny tomorrow.", "options": [{"id": "o1", "label": "will be"}, {"id": "o2", "label": "is being"}]}]}$j$::jsonb,10);
