INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('29b74970-1456-573e-919a-162f94875b0c','a0000000-0000-4000-8000-0000000000a2','Блок 16. The Infinitive (to-infinitive / bare infinitive; let & make)',16,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d521a697-137b-5ae9-a326-693ced8a763e','29b74970-1456-573e-919a-162f94875b0c','The Infinitive (to-infinitive / bare infinitive; let & make)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the to-infinitive after certain verbs (want, hope, would like, promise, expect, decide), after adjectives (happy, glad), and after 'too + adjective': I want to buy a phone. I'm too tired to play football."}, {"type": "rule", "text": "We use the infinitive without 'to' (bare infinitive) after modal verbs (can, may, will, shall) and after 'let's': Let's go to the beach. I can show you."}, {"type": "rule", "text": "After 'let' and 'make' we use the bare infinitive: My parents let me go out. Her parents made her stay in."}, {"type": "examples", "items": ["I've always wanted to try pannacotta.", "I don't know how to send an email.", "They will let me come."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('05812123-1adf-5c90-8089-02cc1f58d7b6','d521a697-137b-5ae9-a326-693ced8a763e',0,'FILL_BLANK','Поставьте глагол в скобках в правильную форму: to-infinitive или bare infinitive.',$j${"items": [{"before": "A: What would you like", "after": "(have) for dessert?"}, {"before": "B: I've always wanted", "after": "(try) pannacotta."}, {"before": "A: I don't know how", "after": "(send) an email."}, {"before": "B: I can", "after": "(show) you."}, {"before": "B: Thanks, but I'm too tired", "after": "(go) out tonight."}, {"before": "A: Can you", "after": "(stop) talking?"}, {"before": "B: Her parents made her", "after": "(stay) in."}, {"before": "A: Jane was happy", "after": "(pass) her exams."}, {"before": "B: Let's", "after": "(go) to the beach."}, {"before": "A: Did you ask Tom", "after": "(give) you Tony's phone number?"}, {"before": "A: Would you like me", "after": "(cook) some pasta tonight?"}, {"before": "A: Do you expect", "after": "(travel) abroad this summer?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('05812123-1adf-5c90-8089-02cc1f58d7b6',$j${"items": [{"accept": ["to have"]}, {"accept": ["to try"]}, {"accept": ["to send"]}, {"accept": ["show"]}, {"accept": ["to go"]}, {"accept": ["stop"]}, {"accept": ["stay"]}, {"accept": ["to pass"]}, {"accept": ["go"]}, {"accept": ["to give"]}, {"accept": ["to cook"]}, {"accept": ["to travel"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f7325a6e-5abc-57f5-8704-ec1ef131bb19','d521a697-137b-5ae9-a326-693ced8a763e',1,'FILL_BLANK','Прочитайте письмо и поставьте глаголы в скобках в правильную форму инфинитива.',$j${"items": [{"before": "I hope that I will be able", "after": "(come)."}, {"before": "I need", "after": "(ask) my parents for permission,"}, {"before": "but I think they will", "after": "(let) me come."}, {"before": "It will be so nice", "after": "(see) you again."}, {"before": "What birthday presents are you expecting", "after": "(receive)?"}, {"before": "Is there anything special you would like me", "after": "(buy) for you?"}, {"before": "I don't remember how", "after": "(get) to your new house."}, {"before": "I can't wait", "after": "(see) you next week!"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f7325a6e-5abc-57f5-8704-ec1ef131bb19',$j${"items": [{"accept": ["to come"]}, {"accept": ["to ask"]}, {"accept": ["let"]}, {"accept": ["to see"]}, {"accept": ["to receive"]}, {"accept": ["to buy"]}, {"accept": ["to get"]}, {"accept": ["to see"]}]}$j$::jsonb,'');
