INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('5da2dd97-894d-52e8-ac84-b8793103800b','a0000000-0000-4000-8000-0000000000a2','Блок 17. Revision 1 (Units 1-3): to be, articles, pronouns, possessives, plurals, prepositions, have got, present simple',17,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c935b0f0-b5c2-5f0b-bcd6-1a44cc439b5e','5da2dd97-894d-52e8-ac84-b8793103800b','Revision 1 (Units 1-3): to be, articles, pronouns, possessives, plurals, prepositions, have got, present simple',0,'LESSON',70,$j$[{"type": "rule", "text": "The verb 'to be': am (I), is (he/she/it and singular nouns), are (you/we/they and plural nouns). Negative: I'm not, he/she/it isn't, you/we/they aren't."}, {"type": "rule", "text": "Use 'a' before a consonant sound and 'an' before a vowel sound: a table, an eraser."}, {"type": "rule", "text": "Subject pronouns: I, you, he, she, it, we, they. Possessive adjectives: my, your, his, her, its, our, their."}, {"type": "rule", "text": "Possessive case: add 's to a singular noun (the boy's dog) and only ' to a plural noun ending in -s (the girls' umbrellas)."}, {"type": "rule", "text": "Plurals take -s; nouns ending in -s/-sh/-ch/-x take -es (toothbrush -> toothbrushes). Some are irregular: tooth -> teeth, knife -> knives."}, {"type": "rule", "text": "'have/has got' shows possession (I have got, she has got; negative haven't/hasn't got). Use this/these for things near you, that/those for things far away, and There is/There are to say that something exists."}, {"type": "rule", "text": "Present simple describes habits and permanent states. Adverbs of frequency (always, usually, sometimes, never) go before the main verb: she never drinks tea."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('df5b1a99-cdf5-5a57-93a0-cefa064ce8a6','c935b0f0-b5c2-5f0b-bcd6-1a44cc439b5e',0,'CHOOSE','Обведите правильный вариант.',$j${"items": [{"before": "A:", "after": "is your birthday? B: June 3rd.", "options": [{"id": "o1", "label": "Where"}, {"id": "o2", "label": "When"}, {"id": "o3", "label": "Which"}]}, {"before": "", "after": "name is Katie.", "options": [{"id": "o1", "label": "His"}, {"id": "o2", "label": "Her"}, {"id": "o3", "label": "Our"}]}, {"before": "Lisa", "after": "arrives early. She's never late.", "options": [{"id": "o1", "label": "sometimes"}, {"id": "o2", "label": "usually"}, {"id": "o3", "label": "always"}]}, {"before": "This is", "after": "eraser.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}, {"id": "o3", "label": "-"}]}, {"before": "John", "after": "my best friend.", "options": [{"id": "o1", "label": "are"}, {"id": "o2", "label": "am"}, {"id": "o3", "label": "is"}]}, {"before": "A:", "after": "is your sister's name? B: Jennifer.", "options": [{"id": "o1", "label": "Who"}, {"id": "o2", "label": "What"}, {"id": "o3", "label": "Whose"}]}, {"before": "A: Whose pencil case is this? B: It's", "after": "", "options": [{"id": "o1", "label": "Jacob"}, {"id": "o2", "label": "Jacobs'"}, {"id": "o3", "label": "Jacob's"}]}, {"before": "There is a table", "after": "the kitchen.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}, {"id": "o3", "label": "under"}]}, {"before": "Helen", "after": "got two cars. She's got one.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "have"}, {"id": "o3", "label": "hasn't"}]}, {"before": "Juan is Spanish. He", "after": "French.", "options": [{"id": "o1", "label": "'m not"}, {"id": "o2", "label": "isn't"}, {"id": "o3", "label": "aren't"}]}, {"before": "This is Tom and Nancy.", "after": "are my cousins.", "options": [{"id": "o1", "label": "They"}, {"id": "o2", "label": "You"}, {"id": "o3", "label": "We"}]}, {"before": "", "after": "are lots of hotels in the city.", "options": [{"id": "o1", "label": "Those"}, {"id": "o2", "label": "These"}, {"id": "o3", "label": "There"}]}, {"before": "Crocodiles have got big", "after": ".", "options": [{"id": "o1", "label": "teeth"}, {"id": "o2", "label": "tooths"}, {"id": "o3", "label": "teeths"}]}, {"before": "There are two", "after": "in the bathroom.", "options": [{"id": "o1", "label": "toothbrush"}, {"id": "o2", "label": "toothbrushes"}, {"id": "o3", "label": "toothbrushs"}]}, {"before": "", "after": "cameras are from Japan.", "options": [{"id": "o1", "label": "This"}, {"id": "o2", "label": "These"}, {"id": "o3", "label": "That"}]}, {"before": "", "after": "you like apples?", "options": [{"id": "o1", "label": "Does"}, {"id": "o2", "label": "Do"}, {"id": "o3", "label": "Doesn't"}]}, {"before": "Sue's house is", "after": "front of Kim's.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "at"}, {"id": "o3", "label": "in"}]}, {"before": "Mark never", "after": "tea.", "options": [{"id": "o1", "label": "drinks"}, {"id": "o2", "label": "doesn't drink"}, {"id": "o3", "label": "drink"}]}, {"before": "She", "after": "goes bowling; she doesn't like it.", "options": [{"id": "o1", "label": "always"}, {"id": "o2", "label": "usually"}, {"id": "o3", "label": "never"}]}, {"before": "They", "after": "two children, Emma and James.", "options": [{"id": "o1", "label": "have got"}, {"id": "o2", "label": "has got"}, {"id": "o3", "label": "haven't got"}]}, {"before": "These are the", "after": "umbrellas.", "options": [{"id": "o1", "label": "girl"}, {"id": "o2", "label": "girl's"}, {"id": "o3", "label": "girls'"}]}, {"before": "This is Richard.", "after": "is twenty.", "options": [{"id": "o1", "label": "He"}, {"id": "o2", "label": "She"}, {"id": "o3", "label": "His"}]}, {"before": "There are some", "after": "on the table.", "options": [{"id": "o1", "label": "banana"}, {"id": "o2", "label": "bananas"}, {"id": "o3", "label": "banana's"}]}, {"before": "She", "after": "got a computer in her bedroom.", "options": [{"id": "o1", "label": "'s"}, {"id": "o2", "label": "is"}, {"id": "o3", "label": "'ve"}]}, {"before": "My name", "after": "Pat.", "options": [{"id": "o1", "label": "'m"}, {"id": "o2", "label": "'re"}, {"id": "o3", "label": "'s"}]}]}$j$::jsonb,10);
