INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('b42f234a-530b-5427-aa68-8cff47f80ec4','a0000000-0000-4000-8000-0000000000a2','Блок 18. Revision 2 (Units 4-6): present simple, present continuous, prepositions, possessives, plurals, quantifiers',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8942bc65-ada6-5f2e-a2d7-8ba92a79038a','b42f234a-530b-5427-aa68-8cff47f80ec4','Revision 2 (Units 4-6): present simple, present continuous, prepositions, possessives, plurals, quantifiers',0,'LESSON',70,$j$[{"type": "rule", "text": "Present simple describes habits, routines and permanent states; questions and negatives use do/does (Do elephants live...?, She doesn't like it)."}, {"type": "rule", "text": "Present continuous (am/is/are + verb-ing) describes an action happening now/at the moment (Sally is having a shower) or a fixed arrangement in the near future (We are catching the flight tomorrow)."}, {"type": "rule", "text": "Stative verbs (want, like, know, need) are normally used in the present simple, not the continuous."}, {"type": "rule", "text": "Prepositions: next to, behind, under, in, on. Use 'any' in questions and negatives, 'some' in affirmatives. There is/There are say that something exists."}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b1d98e40-11fc-567c-ac7d-b9ad2e401df1','8942bc65-ada6-5f2e-a2d7-8ba92a79038a',0,'CHOOSE','Обведите правильный вариант.',$j${"items": [{"before": "Sally is", "after": "a shower at the moment.", "options": [{"id": "o1", "label": "has"}, {"id": "o2", "label": "having"}, {"id": "o3", "label": "have"}]}, {"before": "Katie", "after": "her grandparents every weekend.", "options": [{"id": "o1", "label": "visits"}, {"id": "o2", "label": "visit"}, {"id": "o3", "label": "is visiting"}]}, {"before": "", "after": "Peter and Mark want to go to the football match?", "options": [{"id": "o1", "label": "Does"}, {"id": "o2", "label": "Do"}, {"id": "o3", "label": "Are"}]}, {"before": "A: Where is my pencil case? B: It's", "after": "to your school bag.", "options": [{"id": "o1", "label": "behind"}, {"id": "o2", "label": "under"}, {"id": "o3", "label": "next"}]}, {"before": "Do you like", "after": "new car?", "options": [{"id": "o1", "label": "mine"}, {"id": "o2", "label": "my"}, {"id": "o3", "label": "me"}]}, {"before": "This is the", "after": "dog.", "options": [{"id": "o1", "label": "boy's"}, {"id": "o2", "label": "boys"}, {"id": "o3", "label": "boy"}]}, {"before": "Have", "after": "got a laptop?", "options": [{"id": "o1", "label": "she"}, {"id": "o2", "label": "it"}, {"id": "o3", "label": "you"}]}, {"before": "There are some", "after": "in the drawer.", "options": [{"id": "o1", "label": "knife"}, {"id": "o2", "label": "knifes"}, {"id": "o3", "label": "knives"}]}, {"before": "A:", "after": "is this? B: It's a computer game.", "options": [{"id": "o1", "label": "How"}, {"id": "o2", "label": "What"}, {"id": "o3", "label": "Who"}]}, {"before": "I", "after": "to go to the bank today.", "options": [{"id": "o1", "label": "need"}, {"id": "o2", "label": "am needing"}, {"id": "o3", "label": "needs"}]}, {"before": "Do elephants", "after": "in the jungle?", "options": [{"id": "o1", "label": "live"}, {"id": "o2", "label": "lives"}, {"id": "o3", "label": "living"}]}, {"before": "They have got three", "after": ".", "options": [{"id": "o1", "label": "puppy"}, {"id": "o2", "label": "puppy's"}, {"id": "o3", "label": "puppies"}]}, {"before": "My sister", "after": "Italian.", "options": [{"id": "o1", "label": "speaks"}, {"id": "o2", "label": "is speaking"}, {"id": "o3", "label": "speak"}]}, {"before": "A: Is this", "after": "bike? B: No, this isn't my bike.", "options": [{"id": "o1", "label": "her"}, {"id": "o2", "label": "his"}, {"id": "o3", "label": "your"}]}, {"before": "I", "after": "to school every morning.", "options": [{"id": "o1", "label": "walk"}, {"id": "o2", "label": "am walking"}, {"id": "o3", "label": "walks"}]}, {"before": "A: Where is Sam? B: He's", "after": "the garage.", "options": [{"id": "o1", "label": "under"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "on"}]}, {"before": "Do you know Mario and Andrea?", "after": "are from Italy.", "options": [{"id": "o1", "label": "Their"}, {"id": "o2", "label": "Them"}, {"id": "o3", "label": "They"}]}, {"before": "Are there", "after": "biscuits left?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "a"}, {"id": "o3", "label": "any"}]}, {"before": "We", "after": "the 12 o'clock flight to New York tomorrow.", "options": [{"id": "o1", "label": "catch"}, {"id": "o2", "label": "are catching"}, {"id": "o3", "label": "catches"}]}, {"before": "That's not Tom's jacket.", "after": "jacket is in the wardrobe.", "options": [{"id": "o1", "label": "Her"}, {"id": "o2", "label": "His"}, {"id": "o3", "label": "your"}]}, {"before": "That isn't Sally's dog. It's", "after": ".", "options": [{"id": "o1", "label": "Jakes"}, {"id": "o2", "label": "Jake's"}, {"id": "o3", "label": "Jake"}]}, {"before": "A:", "after": "are you going out to dinner with? B: Sally and Jeff.", "options": [{"id": "o1", "label": "Why"}, {"id": "o2", "label": "Where"}, {"id": "o3", "label": "Who"}]}, {"before": "", "after": "are some kittens in the garden.", "options": [{"id": "o1", "label": "There"}, {"id": "o2", "label": "They"}, {"id": "o3", "label": "This"}]}, {"before": "The children", "after": "football in the park now.", "options": [{"id": "o1", "label": "play"}, {"id": "o2", "label": "is playing"}, {"id": "o3", "label": "are playing"}]}, {"before": "Peter and Maria are sixteen. They", "after": "eighteen.", "options": [{"id": "o1", "label": "isn't"}, {"id": "o2", "label": "aren't"}, {"id": "o3", "label": "'m not"}]}]}$j$::jsonb,10);
