INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('c249a80e-b43c-5075-9791-11a8df7bbbbd','a0000000-0000-4000-8000-0000000000a2','Блок 19. Present Simple vs Present Continuous',19,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b7dc5218-cf90-53df-a907-30415d2b40e0','c249a80e-b43c-5075-9791-11a8df7bbbbd','Present Simple vs Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "Present simple is used for permanent states, habits and routines. Time expressions: every day, usually, always, sometimes, on Saturdays, twice a week."}, {"type": "rule", "text": "Present continuous (am/is/are + verb-ing) is used for an action happening at the time of speaking, a temporary situation, or a fixed arrangement in the near future. Time expressions: now, at the moment, at present, tonight, this week."}, {"type": "rule", "text": "Spelling of the -ing form: verbs like 'put' double the final consonant (putting); verbs ending in -e like 'write' drop the -e (writing)."}, {"type": "rule", "text": "Questions/negatives: present simple uses do/does (+ not); present continuous uses the verb 'to be' (am/is/are) (+ not). Stative verbs (want, like, know, need) are not usually used in the continuous."}, {"type": "examples", "items": ["We are staying at a nice hotel in Naples. (temporary situation)", "It happens every year in September. (habit/routine)", "Fabio lives in Rome. (permanent state)", "This afternoon, we're driving to Mt Vesuvius. (fixed arrangement)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('242e5dc1-3fe2-59d2-bfa9-8463148d4929','b7dc5218-cf90-53df-a907-30415d2b40e0',0,'FILL_BLANK','Поставьте глаголы в present simple или present continuous.',$j${"items": [{"before": "A: What", "after": "this weekend? (Helen/do)"}, {"before": "B: She", "after": "her cousin in Manchester. (visit)"}, {"before": "A: What", "after": "on Saturday mornings? (you/usually/do)"}, {"before": "B: I", "after": "my room and go shopping. (tidy)"}, {"before": "B: She's in London. She", "after": "at the Hilton Hotel. (stay)"}, {"before": "A: How often", "after": "the plants? (you/water)"}, {"before": "A:", "after": "to come over tonight? (you/want)"}, {"before": "B: I'm sorry, I can't. I", "after": "out to dinner with some friends. (go)"}, {"before": "A: What time", "after": "every day? (you/get up)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('242e5dc1-3fe2-59d2-bfa9-8463148d4929',$j${"items": [{"accept": ["is Helen doing"]}, {"accept": ["is visiting", "'s visiting"]}, {"accept": ["do you usually do"]}, {"accept": ["tidy"]}, {"accept": ["is staying", "'s staying"]}, {"accept": ["do you water"]}, {"accept": ["Do you want"]}, {"accept": ["am going", "'m going"]}, {"accept": ["do you get up"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('51595bc0-544b-5a34-b20a-5d83847533db','b7dc5218-cf90-53df-a907-30415d2b40e0',1,'CHOOSE','Обведите правильное выражение времени.',$j${"items": [{"before": "Martha usually does her food shopping", "after": ".", "options": [{"id": "o1", "label": "on Saturdays"}, {"id": "o2", "label": "at the moment"}]}, {"before": "It isn't raining", "after": ".", "options": [{"id": "o1", "label": "now"}, {"id": "o2", "label": "at the weekend"}]}, {"before": "Pierre and Marie are going to the theatre", "after": ".", "options": [{"id": "o1", "label": "tonight"}, {"id": "o2", "label": "every Tuesday"}]}, {"before": "Ron has a piano lesson", "after": ".", "options": [{"id": "o1", "label": "twice a week"}, {"id": "o2", "label": "these days"}]}, {"before": "Sophie is sitting her exams", "after": ".", "options": [{"id": "o1", "label": "this week"}, {"id": "o2", "label": "at night"}]}, {"before": "Carla and John usually eat out", "after": ".", "options": [{"id": "o1", "label": "on Sundays"}, {"id": "o2", "label": "at the moment"}]}, {"before": "George buys a newspaper", "after": ".", "options": [{"id": "o1", "label": "every day"}, {"id": "o2", "label": "today"}]}, {"before": "My friend and I play computer games", "after": ".", "options": [{"id": "o1", "label": "on Saturday afternoons"}, {"id": "o2", "label": "at present"}]}, {"before": "", "after": "she is studying for a test.", "options": [{"id": "o1", "label": "Sometimes"}, {"id": "o2", "label": "At the moment"}]}, {"before": "Tom isn't driving to work", "after": ".", "options": [{"id": "o1", "label": "today"}, {"id": "o2", "label": "every day"}]}]}$j$::jsonb,10);
