INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('755bbcd5-74de-5237-8260-9629c34a75cc','a0000000-0000-4000-8000-0000000000a2','Блок 24. Conditionals, Question Tags & Comparatives',24,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('05230514-e8e5-5ee2-af92-7fadb302c386','755bbcd5-74de-5237-8260-9629c34a75cc','Conditionals, Question Tags & Comparatives',0,'LESSON',70,$j$[{"type": "rule", "text": "Conditionals: Type 0 (general truth) = if + present, present; Type 1 (real future) = if + present, will + verb; Type 2 (unreal/imaginary) = if + past, would + verb."}, {"type": "rule", "text": "Question tags: a positive statement takes a negative tag and a negative statement takes a positive tag; the tag repeats the auxiliary (or uses do/does/did for the present/past simple)."}, {"type": "examples", "items": ["If it rains, I will stay at home.", "If I were you, I would tell her the truth.", "She comes from Madrid, doesn't she?", "He isn't coming, is he?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('73c609f2-dee4-5dee-a4be-6b5aef2c76a5','05230514-e8e5-5ee2-af92-7fadb302c386',0,'MATCH_PAIRS','Соедините части предложений, чтобы получились условные предложения.',$j${"left": [{"id": "l1", "label": "We won't go to the party"}, {"id": "l2", "label": "He will help you"}, {"id": "l3", "label": "When it's hot,"}, {"id": "l4", "label": "If we fail our test,"}, {"id": "l5", "label": "We get green"}, {"id": "l6", "label": "If they leave now,"}, {"id": "l7", "label": "I would tell her the truth"}, {"id": "l8", "label": "He can borrow my bike"}], "right": [{"id": "r1", "label": "if we mix blue and yellow."}, {"id": "r2", "label": "if he promises to ride it carefully."}, {"id": "r3", "label": "if you don't come with us."}, {"id": "r4", "label": "if I were you."}, {"id": "r5", "label": "people wear light clothes."}, {"id": "r6", "label": "if you ask him."}, {"id": "r7", "label": "our teacher will be upset."}, {"id": "r8", "label": "they will catch the 7:30 bus."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('73c609f2-dee4-5dee-a4be-6b5aef2c76a5',$j${"pairs": [{"l": "l1", "r": "r3"}, {"l": "l2", "r": "r6"}, {"l": "l3", "r": "r5"}, {"l": "l4", "r": "r7"}, {"l": "l5", "r": "r1"}, {"l": "l6", "r": "r8"}, {"l": "l7", "r": "r4"}, {"l": "l8", "r": "r2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3a3a0f82-5d34-56c9-bba2-935701650fef','05230514-e8e5-5ee2-af92-7fadb302c386',1,'FILL_BLANK','Впишите правильный разделительный вопрос (question tag).',$j${"items": [{"before": "Let's go out,", "after": "?"}, {"before": "He isn't coming,", "after": "?"}, {"before": "They left yesterday,", "after": "?"}, {"before": "Stella is never late,", "after": "?"}, {"before": "She comes from Madrid,", "after": "?"}, {"before": "They didn't invite Pete to the party,", "after": "?"}, {"before": "She is making the bed,", "after": "?"}, {"before": "The children are sleeping,", "after": "?"}, {"before": "He walks to work,", "after": "?"}, {"before": "There's something wrong,", "after": "?"}, {"before": "They had a great time at the party,", "after": "?"}, {"before": "He didn't call,", "after": "?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3a3a0f82-5d34-56c9-bba2-935701650fef',$j${"items": [{"accept": ["shall we"]}, {"accept": ["is he"]}, {"accept": ["didn't they"]}, {"accept": ["is she"]}, {"accept": ["doesn't she"]}, {"accept": ["did they"]}, {"accept": ["isn't she"]}, {"accept": ["aren't they"]}, {"accept": ["doesn't he"]}, {"accept": ["isn't there"]}, {"accept": ["didn't they"]}, {"accept": ["did he"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3d5a6db0-5b34-5666-9976-e4fd9d8524b6','05230514-e8e5-5ee2-af92-7fadb302c386',2,'FILL_BLANK','Поставьте прилагательное в скобках в правильную форму (сравнительную или превосходную).',$j${"items": [{"before": "Who's your", "after": "friend? (good)"}, {"before": "He is two years", "after": "than me. (old)"}, {"before": "He's the", "after": "person I know. (clever)"}, {"before": "Steve is the", "after": "person I know. (boring)"}, {"before": "He thinks he's the", "after": "person in the world. (funny)"}, {"before": "Ann is a lot", "after": "than Kate. (helpful)"}, {"before": "Kate is the", "after": "person I know. (arrogant)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3d5a6db0-5b34-5666-9976-e4fd9d8524b6',$j${"items": [{"accept": ["best"]}, {"accept": ["older"]}, {"accept": ["cleverest"]}, {"accept": ["most boring"]}, {"accept": ["funniest"]}, {"accept": ["more helpful"]}, {"accept": ["most arrogant"]}]}$j$::jsonb,'');
