INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a93e4575-59ef-5ab3-ac66-a8f144f8b400','98f7395c-62a5-509a-9a8c-2f69a81466b4','Relative Clauses & -ing / Infinitive',0,'LESSON',70,$j$[{"type": "rule", "text": "Relative pronouns: who = for people, which = for things/animals, whose = for possession."}, {"type": "rule", "text": "Some verbs are followed by the full infinitive (want, decide, promise, would like), others by the -ing form (fancy, enjoy, don't mind, look forward to, stop, be busy). After make/let and modal verbs use the bare infinitive."}, {"type": "examples", "items": ["This is the man who helped us.", "That's the woman whose car was stolen.", "He decided to buy a new car.", "I'm looking forward to seeing you."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('95e3d292-9daf-54e9-87d8-cb9faf857374','a93e4575-59ef-5ab3-ac66-a8f144f8b400',0,'FILL_BLANK','Впишите who, which или whose, чтобы объединить предложения.',$j${"items": [{"before": "Mrs Jones,", "after": "is a nurse, works in the Memorial hospital."}, {"before": "Jane has a son", "after": "name is Peter."}, {"before": "These are the men", "after": "helped us."}, {"before": "Tony went to see his daughter,", "after": "lives in Australia."}, {"before": "Elephants have got trunks", "after": "they use to pick up things."}, {"before": "I met Mr Smith", "after": "wife knows you."}, {"before": "Seals have got flat legs", "after": "are called flippers."}, {"before": "This is Steven", "after": "bicycle I borrowed."}]}$j$::jsonb,10);
