INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('d32ebec1-89b1-50d2-bf14-1755bc656d14','2269858a-05a4-5627-8ec8-dcf723c305cc','Irregular Verbs',0,'LESSON',70,$j$[{"type": "rule", "text": "Irregular verbs do not form their past simple and past participle with -ed. You have to learn the three forms: infinitive, past simple and past participle."}, {"type": "examples", "items": ["go – went – gone", "buy – bought – bought", "break – broke – broken", "write – wrote – written", "eat – ate – eaten"]}]$j$::jsonb);
